package cn.qiuc.invoice;

import android.content.*;
import android.database.Cursor;
import android.database.sqlite.SQLiteDatabase;
import org.json.*;
import java.util.*;

/** Phone-owned maintenance and conservative draft-only matching. */
public final class Workbench {
    private final Ledger ledger;
    public Workbench(Ledger ledger){this.ledger=ledger;}
    private static String name(JSONObject a){String s=a.optString("name").trim();if(s.isEmpty()||s.length()>120)throw new IllegalArgumentException("名称不能为空，最多120字");return s;}
    public Object call(String method,JSONObject a) throws Exception{
        synchronized(ledger){SQLiteDatabase db=ledger.getWritableDatabase();db.beginTransaction();try{Object result;
            switch(method){
                case "projectEdit":{String id=a.getString("id");ContentValues v=new ContentValues();if(a.has("name"))v.put("name",name(a));if(a.has("pinned"))v.put("pinned",a.getBoolean("pinned")?1:0);if(a.has("deleted"))v.put("deleted",a.getBoolean("deleted")?1:0);if(v.size()==0||db.update("projects",v,"id=?",new String[]{id})!=1)throw new IllegalArgumentException("项目不存在");result=true;break;}
                case "person":{String project=a.getString("project_id"),id=a.optString("id");if(id.isEmpty()){result=new JSONObject().put("id",ledger.personForName(db,project,name(a)));break;}String old;try(Cursor c=db.rawQuery("SELECT name FROM people WHERE id=? AND project_id=?",new String[]{id,project})){if(!c.moveToFirst())throw new IllegalArgumentException("人员不存在");old=c.getString(0);}String newName=a.has("name")?name(a):old;try(Cursor duplicate=db.rawQuery("SELECT id FROM people WHERE project_id=? AND name=? AND id!=? AND active=1",new String[]{project,newName,id})){if(duplicate.moveToFirst())throw new IllegalArgumentException("已有同名人员，请使用合并功能或区分姓名");}ContentValues v=new ContentValues();v.put("name",newName);if(a.has("active"))v.put("active",a.getBoolean("active")?1:0);db.update("people",v,"id=?",new String[]{id});rewritePeople(db,project,id,id,newName);result=true;break;}
                case "mergePeople":{String project=a.getString("project_id"),from=a.getString("from"),to=a.getString("to");if(from.equals(to))throw new IllegalArgumentException("请选择不同的人员");String newName;try(Cursor c=db.rawQuery("SELECT name FROM people WHERE id=? AND project_id=? AND active=1",new String[]{to,project})){if(!c.moveToFirst())throw new IllegalArgumentException("目标人员无效");newName=c.getString(0);}if(db.delete("people","id=? AND project_id=?",new String[]{from,project})!=1)throw new IllegalArgumentException("原人员不存在");rewritePeople(db,project,from,to,newName);result=true;break;}
                case "materialEdit":{String id=a.getString("id");JSONObject fields;try(Cursor c=db.rawQuery("SELECT fields FROM materials WHERE id=? AND expense_id IS NULL",new String[]{id})){if(!c.moveToFirst())throw new IllegalArgumentException("请先退回并解除材料关联");fields=new JSONObject(c.getString(0));}JSONObject changes=a.getJSONObject("fields");JSONArray manual=fields.optJSONArray("manual_fields");Set<String> protectedFields=new LinkedHashSet<>();if(manual!=null)for(int i=0;i<manual.length();i++)protectedFields.add(manual.getString(i));for(String key:List.of("amount","date","merchant","invoice_number","order_number","shopping_platform","shop_name","payment_channel"))if(changes.has(key)){String value=changes.getString(key).trim();if(value.length()>500)throw new IllegalArgumentException("字段过长");if(key.equals("amount")&&!value.isEmpty())Rules.cents(value);if(key.equals("date")&&!value.isEmpty())Rules.date(value);fields.put(key,value);protectedFields.add(key);}fields.put("manual_fields",new JSONArray(protectedFields));db.execSQL("UPDATE materials SET fields=?,version=version+1 WHERE id=?",new Object[]{fields.toString(),id});result=true;break;}
                case "materialStatus":{String status=a.getString("status");if(!Set.of("active","archived","deleted").contains(status))throw new IllegalArgumentException("材料状态无效");ContentValues v=new ContentValues();v.put("status",status);if(db.update("materials",v,"id=? AND expense_id IS NULL",new String[]{a.getString("id")})!=1)throw new IllegalArgumentException("已关联的材料不能归档或删除");result=true;break;}
                case "detach":{String expense=a.getString("expense_id"),material=a.getString("material_id");try(Cursor c=db.rawQuery("SELECT state FROM expenses WHERE id=?",new String[]{expense})){if(!c.moveToFirst()||!c.getString(0).equals("review"))throw new IllegalArgumentException("先退回待核对，才能拆分材料");}db.execSQL("UPDATE materials SET expense_id=NULL,version=version+1 WHERE id=? AND expense_id=?",new Object[]{material,expense});db.execSQL("UPDATE expenses SET version=version+1 WHERE id=?",new Object[]{expense});result=true;break;}
                case "attach":{String expense=a.getString("expense_id");String project;try(Cursor c=db.rawQuery("SELECT project_id FROM expenses WHERE id=? AND state='review' AND deleted=0",new String[]{expense})){if(!c.moveToFirst())throw new IllegalArgumentException("仅可向待核对费用追加材料");project=c.getString(0);}JSONArray ids=a.getJSONArray("ids");for(int i=0;i<ids.length();i++){ContentValues v=new ContentValues();v.put("expense_id",expense);if(db.update("materials",v,"id=? AND project_id=? AND expense_id IS NULL AND status='active'",new String[]{ids.getString(i),project})!=1)throw new IllegalArgumentException("材料已被使用或项目不一致");}db.execSQL("UPDATE expenses SET version=version+1 WHERE id=?",new Object[]{expense});result=true;break;}
                case "expenseBatch":{JSONArray ids=a.getJSONArray("ids");String action=a.getString("action");JSONArray confirmations=new JSONArray();for(int i=0;i<ids.length();i++){String id=ids.getString(i);if(action.equals("verify")){JSONObject answer=ledger.verify(id,a.optBoolean("confirm_missing"));if(answer.optBoolean("requires_confirmation"))confirmations.put(new JSONObject().put("id",id).put("missing",answer.getJSONArray("missing")));}else if(action.equals("return"))ledger.returnReview(id);else{JSONObject e;String project,state;try(Cursor c=db.rawQuery("SELECT project_id,data,state FROM expenses WHERE id=?",new String[]{id})){if(!c.moveToFirst())throw new IllegalArgumentException("费用不存在");project=c.getString(0);e=new JSONObject(c.getString(1));state=c.getString(2);}if(action.equals("delete")||action.equals("restore")){if(state.equals("submitted")&&action.equals("delete"))throw new IllegalArgumentException("先退回待核对，再删除已提交费用");db.execSQL("UPDATE expenses SET deleted=?,version=version+1 WHERE id=?",new Object[]{action.equals("delete")?1:0,id});continue;}if(!state.equals("review"))throw new IllegalArgumentException("请先退回待核对，再批量修改");if(action.equals("owner")){String owner=name(a);e.put("owner",owner).put("owner_id",ledger.personForName(db,project,owner));e.remove("allocations");}else if(action.equals("type")){JSONObject choice=ReportModel.choice(a.getString("project_type"),a.getString("project_name"),e.optString("category"));for(String key:List.of("project_type","project_name","category"))e.put(key,choice.getString(key));}else if(action.equals("move")){String destination=a.getString("destination");try(Cursor c=db.rawQuery("SELECT id FROM projects WHERE id=? AND deleted=0",new String[]{destination})){if(!c.moveToFirst())throw new IllegalArgumentException("目标项目不存在");}if(e.optJSONArray("allocations")!=null&&e.getJSONArray("allocations").length()>0)throw new IllegalArgumentException("分摊费用请先取消分摊再移动项目");if(!e.optString("owner").isEmpty())e.put("owner_id",ledger.personForName(db,destination,e.getString("owner")));db.execSQL("UPDATE materials SET project_id=? WHERE expense_id=?",new Object[]{destination,id});db.execSQL("UPDATE expenses SET project_id=? WHERE id=?",new Object[]{destination,id});}else throw new IllegalArgumentException("批量操作无效");db.execSQL("UPDATE expenses SET data=?,version=version+1 WHERE id=?",new Object[]{e.toString(),id});}}
                    // Missing-material confirmation is atomic: no earlier row silently passes.
                    if(confirmations.length()>0)return new JSONObject().put("requires_confirmation",true).put("items",confirmations);
                    result=true;break;}
                case "experience":{String key=a.getString("key").trim();if(key.isEmpty()||key.length()>200)throw new IllegalArgumentException("请填写明确商品关键词");String category=a.getString("category");if(!Rules.CATEGORIES.contains(category))throw new IllegalArgumentException("类别无效");db.execSQL("INSERT OR REPLACE INTO experience(key,value,enabled) VALUES(?,?,?)",new Object[]{key,category,a.optBoolean("enabled",true)?1:0});result=true;break;}
                case "autoMatch":result=match(a.getString("project_id"),a.optBoolean("apply"));break;
                default:throw new IllegalArgumentException("不支持的工作台操作");
            }ledger.event(db,method,a.optString("id",a.optString("project_id")));db.setTransactionSuccessful();return result;
        }finally{db.endTransaction();}}
    }
    private void rewritePeople(SQLiteDatabase db,String project,String from,String to,String name) throws Exception{
        try(Cursor c=db.rawQuery("SELECT id,data FROM expenses WHERE project_id=?",new String[]{project})){while(c.moveToNext()){JSONObject e=new JSONObject(c.getString(1));boolean change=false;if(e.optString("owner_id").equals(from)){e.put("owner_id",to).put("owner",name);change=true;}JSONArray shares=e.optJSONArray("allocations");if(shares!=null){Map<String,JSONObject> combined=new LinkedHashMap<>();for(JSONObject share:ReportModel.list(shares)){if(share.getString("person_id").equals(from)){share.put("person_id",to).put("name",name);change=true;}String id=share.getString("person_id");if(combined.containsKey(id))combined.get(id).put("cents",combined.get(id).getLong("cents")+share.getLong("cents"));else combined.put(id,share);}if(change)e.put("allocations",new JSONArray(combined.values()));}if(change)db.execSQL("UPDATE expenses SET data=?,version=version+1 WHERE id=?",new Object[]{e.toString(),c.getString(0)});}}
    }
    public void recognized(String id,Map<String,String> proposed,String text) throws Exception{
        synchronized(ledger){SQLiteDatabase db=ledger.getWritableDatabase();try(Cursor c=db.rawQuery("SELECT fields,role FROM materials WHERE id=? AND expense_id IS NULL",new String[]{id})){if(!c.moveToFirst())throw new IllegalArgumentException("仅可重新识别未关联的材料");JSONObject fields=new JSONObject(c.getString(0));Set<String> manual=new HashSet<>();JSONArray list=fields.optJSONArray("manual_fields");if(list!=null)for(int i=0;i<list.length();i++)manual.add(list.getString(i));for(Map.Entry<String,String> e:proposed.entrySet())if(!manual.contains(e.getKey())){String prior=fields.optString(e.getKey());if(Set.of("amount","merchant","invoice_number","shop_name").contains(e.getKey())&&!prior.isEmpty()&&!prior.equals(e.getValue()))fields.put("warning","新识别结果与已有字段不同，请对照原件手动确认");else fields.put(e.getKey(),e.getValue());}String role=c.getString(1);if(role.equals("other")&&!fields.optBoolean("manual_role")&&android.database.DatabaseUtils.longForQuery(db,"SELECT COUNT(*) FROM events WHERE kind='material_role_manual' AND subject=?",new String[]{id})==0&&proposed.containsKey("role"))role=proposed.get("role");db.execSQL("UPDATE materials SET fields=?,text=?,role=?,version=version+1 WHERE id=?",new Object[]{fields.toString(),text,role,id});ledger.event(db,"material_recognized",id);}}
    }
    public JSONObject settings()throws Exception{JSONObject out=new JSONObject();try(Cursor c=ledger.getReadableDatabase().rawQuery("SELECT key,value FROM settings",null)){while(c.moveToNext())out.put(c.getString(0),c.getString(1));}JSONArray experiences=new JSONArray();try(Cursor c=ledger.getReadableDatabase().rawQuery("SELECT key,value,enabled FROM experience",null)){while(c.moveToNext())experiences.put(new JSONObject().put("key",c.getString(0)).put("category",c.getString(1)).put("enabled",c.getInt(2)==1));}return out.put("experience",experiences);}
    public String category(String text)throws Exception{try(Cursor c=ledger.getReadableDatabase().rawQuery("SELECT key,value FROM experience WHERE enabled=1 ORDER BY length(key) DESC",null)){while(c.moveToNext())if(text.contains(c.getString(0)))return c.getString(1);}return Rules.categoryFromGoods(OptionalServices.cleanGoods(text));}
    private static String matchShop(JSONObject fields){String shop=fields.optString("shop_name");return shop.isBlank()?fields.optString("merchant"):shop;}
    private JSONObject match(String project,boolean apply)throws Exception{
        List<JSONObject> all=ReportModel.list(ledger.materials(project,null));JSONArray proposals=new JSONArray();Set<String> used=new HashSet<>();int ambiguous=0;
        Map<String,List<JSONObject>> possible=new LinkedHashMap<>();Map<String,Integer> degrees=new HashMap<>();
        for(JSONObject a:all){if(!Set.of("invoice","receipt","purchase","order").contains(a.getString("role")))continue;List<JSONObject> matches=new ArrayList<>();for(JSONObject b:all){if(a.getString("id").equals(b.getString("id"))||!Set.of("payment","trip","detail").contains(b.getString("role")))continue;JSONObject x=a.getJSONObject("fields"),y=b.getJSONObject("fields");String merchant=matchShop(x),other=matchShop(y);if(merchant.isBlank()||!java.text.Normalizer.normalize(merchant,java.text.Normalizer.Form.NFKC).replaceAll("[\\s\\p{P}]","").equals(java.text.Normalizer.normalize(other,java.text.Normalizer.Form.NFKC).replaceAll("[\\s\\p{P}]","")))continue;String platform=x.optString("shopping_platform"),bp=y.optString("shopping_platform");if(!platform.isEmpty()&&!bp.isEmpty()&&!platform.equals(bp))continue;String amount=x.optString("amount"),ba=y.optString("amount");if(amount.isEmpty()||ba.isEmpty()||Rules.cents(amount)!=Rules.cents(ba))continue;matches.add(b);degrees.merge(b.getString("id"),1,Integer::sum);}possible.put(a.getString("id"),matches);}
        for(JSONObject a:all){List<JSONObject> matches=possible.get(a.getString("id"));if(matches==null)continue;if(matches.size()!=1||degrees.getOrDefault(matches.get(0).getString("id"),0)!=1){if(!matches.isEmpty())ambiguous++;continue;}JSONObject b=matches.get(0);if(used.contains(a.getString("id"))||used.contains(b.getString("id")))continue;JSONArray ids=new JSONArray().put(a.getString("id")).put(b.getString("id"));JSONObject fields=a.getJSONObject("fields"),draft=new JSONObject().put("project_id",project).put("material_ids",ids).put("title",fields.optString("merchant")).put("merchant",fields.optString("merchant")).put("date",fields.optString("date").isBlank()?b.getJSONObject("fields").optString("date"):fields.optString("date")).put("amount",fields.optString("amount")).put("owner","").put("category",category(Rules.goods(a.getString("text")))).put("note","唯一明确材料自动组合；仍需人工核对归属人和用途");for(String key:List.of("order_number","shopping_platform","shop_name"))draft.put(key,fields.optString(key));if(apply)draft.put("id",ledger.save(draft).getString("id"));proposals.put(draft);used.add(a.getString("id"));used.add(b.getString("id"));}
        // A whole, bounded one-to-many group is unique only when every positive
        // amount is required to reach the other side. Partial subset guesses stay manual.
        Map<String,List<JSONObject>> groups=new LinkedHashMap<>();for(JSONObject m:all)if(!used.contains(m.getString("id"))&&Set.of("invoice","receipt","purchase","order","payment").contains(m.getString("role"))){JSONObject f=m.getJSONObject("fields");String shop=matchShop(f);if(!shop.isBlank()&&!f.optString("amount").isEmpty())groups.computeIfAbsent(shop+"|"+f.optString("shopping_platform"),k->new ArrayList<>()).add(m);}
        for(List<JSONObject> group:groups.values()){List<JSONObject> bills=new ArrayList<>(),payments=new ArrayList<>();for(JSONObject m:group)(m.getString("role").equals("payment")?payments:bills).add(m);if(!((bills.size()==1&&payments.size()>1)||(payments.size()==1&&bills.size()>1))||bills.size()>6||payments.size()>6)continue;long billTotal=0,paymentTotal=0;boolean valid=true;for(JSONObject m:bills)billTotal=Math.addExact(billTotal,Rules.cents(m.getJSONObject("fields").getString("amount")));for(JSONObject m:payments){JSONObject f=m.getJSONObject("fields");valid&=!Set.of("failed","refunded","unpaid").contains(f.optString("payment_status"));paymentTotal=Math.addExact(paymentTotal,Rules.cents(f.getString("amount")));}if(!valid||billTotal!=paymentTotal)continue;JSONArray ids=new JSONArray();for(JSONObject m:group){ids.put(m.getString("id"));used.add(m.getString("id"));}JSONObject f=bills.get(0).getJSONObject("fields");JSONObject draft=new JSONObject().put("project_id",project).put("material_ids",ids).put("title",f.optString("merchant")).put("merchant",f.optString("merchant")).put("date",f.optString("date")).put("amount",Rules.money(billTotal)).put("owner","").put("category",category(Rules.goods(bills.get(0).getString("text")))).put("note","唯一整组金额对应；归属人、购买内容仍需人工核对");if(apply)draft.put("id",ledger.save(draft).getString("id"));proposals.put(draft);}
        return new JSONObject().put("proposals",proposals).put("ambiguous",ambiguous).put("unmatched",all.size()-used.size());
    }
}
